// Part: room: I-house stair hall. Interior of box [29,3,10,30,6,15]; the flight at x30 z10..14 is the joiner's.
// The hall is two cells wide and the stair takes x30, so x29 is the only lane from the front door (z9) to the
// back door (z16) and to the west and east doors at z11. Nothing goes on x29; the furniture sits in the corner
// cell x30 z15 (out of every doorway's first cell) and the light hangs over the lane at y6, above head height.
import { hanging_lantern } from "../vocab/h2.mjs";
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // Coat stand: a fence post with a standing lantern on top, the focal piece of the hall, seen down the stair
  // from the front door at the far corner by the back door.
  g.set(30, 3, 15, ...B.fence("spruce"));
  g.set(30, 4, 15, ...B.lantern(false));

  // Hanging lantern under the upper floor over the lane (x29 z12): the hall's light, clear of the head room.
  hanging_lantern(g, 29, 6, 12);
}
----
// Part: room: I-house east room. Dining/kitchen, inside the box x32..33, y3..6, z10..15 (door x31 z11 from the hall).
// The lane is the x32 column, kept clear from the door to the stove. Furniture stands in the x33 column: barrels by the
// window, a water cauldron, the stove on the chimney wall (z12), one chair, and a two-cell table at the south end.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { hearth_nook, hanging_lantern } from "../vocab.mjs";

const LEGEND = {
  B: "barrel",
  W: ["water_cauldron", { level: "3" }],
  C: ["spruce_stairs", { facing: "south", half: "bottom", shape: "straight" }],
  T: "spruce_fence",
  S: ["spruce_slab", { type: "top" }],
};

export function build(g) {
  // Floor row (y3): one column per x (32, 33), one row per z (10..15). '.' = leave the cell alone (the lane).
  layers(g, [32, 3, 10], LEGEND, [
    [".B", ".W", "..", ".C", ".T", ".T"],
  ]);
  // Stove: a lit furnace at x33 z12 on the chimney wall, its stone mantle above (hearth_nook writes both cells).
  hearth_nook(g, 33, 3, 12, "west");
  // Table top row (y4) over the table legs at x33 z14..15, and a second barrel stacked on the first.
  layers(g, [32, 4, 10], LEGEND, [
    [".B", "..", "..", "..", ".S", ".S"],
  ]);
  // Lanterns hang from the ceiling (y7): one over the lane by the stove, one over the table.
  hanging_lantern(g, 32, 6, 12);
  hanging_lantern(g, 33, 6, 14);
}
----
// Part: room: I-house upper east bedroom. Inner air x 32..33, y 8..11, z 10..15; door x31 z11 from the upper hall.
// Two white beds, foot z14 and head z15 against the back wall (facing south). A barrel dresser at the north end, a
// washstand (fence and top slab) with a standing lantern, and one hanging lantern over the lane. The lane x32 z11..13
// and the cells beside the beds stay clear from the door to both beds.
import { layers, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const LEGEND = {
  B: "barrel",
  F: "spruce_fence",
  S: ["spruce_slab", { type: "top" }],
  L: ["lantern", { hanging: "false" }],
  H: ["lantern", { hanging: "true" }],
};

export function build(g) {
  // Focal piece: both beds, whole (bed() places foot and head with matching states).
  bed(g, [32, 8, 14], "south", "white");
  bed(g, [33, 8, 14], "south", "white");

  // Furniture as text, origin [32, 8, 10] (x32 z10 is the top-left interior cell); rows run along +x, then +z.
  // '.' and ' ' are left alone. Layer y8: barrel dresser at x32 z10, washstand legs at x33 z10, bedside barrel at x32 z12.
  // Layer y9: washstand top slab, lantern on the bedside barrel. Layer y10: standing lantern on the top slab.
  // The lane runs down x33 (x32 z12 is the barrel), so the path from the door reaches both beds.
  layers(g, [32, 8, 10], LEGEND, [
    ["BF", "..", "B.", "..", "  ", "  "],
    [".S", "..", "L.", "..", "  ", "  "],
    [".L", "..", "..", "..", "  ", "  "],
  ]);
}
