// Part: Windows, doors and porches: every opening in plan OPENINGS, shutters, porch posts and rails (porch_run), tapered
// posts, front steps, the porch sign and the porch lanterns. Builds only into air; the porch roofs belong to Roofs.
import { B, shutter } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import {
  window as win,
  porch_run,
  front_steps,
  shutter_pair,
  hanging_lantern,
} from "../vocab.mjs";

// A single door (both halves) facing out of its wall; skipped unless both cells are air.
function door(g, x, y, z, facing, wood, hinge = "left") {
  if (!g.isAir(x, y, z) || !g.isAir(x, y + 1, z)) return;
  g.set(x, y, z, ...B.door(wood, facing, "lower", hinge));
  g.set(x, y + 1, z, ...B.door(wood, facing, "upper", hinge));
}

// A double door at x, x+1 (hinges mirrored). No step slab: every porch deck already sits at y 2, so the door's
// threshold is the deck and a slab at the door's base would block the walk.
function double(g, x, y, z, facing, wood) {
  door(g, x, y, z, facing, wood, "left");
  door(g, x + 1, y, z, facing, wood, "right");
}

// A tapered porch post (vocab's tapered_post writes pillar ids that are off palette): brick base, brick wall, log cap.
function taperedPost(g, x, y, z) {
  if (g.isAir(x, y, z)) g.set(x, y, z, "bricks", {});
  if (g.isAir(x, y + 1, z)) g.set(x, y + 1, z, "brick_wall", { up: "true" });
  if (g.isAir(x, y + 2, z)) g.set(x, y + 2, z, "stripped_pale_oak_log", { axis: "y" });
}

// A porch sign on the deck: palette has only the standing spruce_sign (hanging_sign writes an off-palette hanging id), so it
// stands on the deck (y 2) just inside the street edge, facing north, clear of the door's walk. Writes only into air.
function porch_sign(g, text, x, y, z) {
  if (!g.isAir(x, y, z) || g.isAir(x, y - 1, z)) return;
  g.set(x, y, z, ...B.sign("spruce", String(text).split("\n"), { wall: false, rotation: 8, dataVersion: g.dataVersion }));
}

// A slatted vent: a closed trapdoor set in the gable cell (the wall plane itself). Open, it would float: the void behind it is not built wall.
function louvre(g, x, y, z, facing, wood) {
  if (!g.isAir(x, y, z)) return;
  g.set(x, y, z, ...B.trapdoor(wood, facing, "bottom", false));
}

export function build(g) {
  // ---- plot 0 dogtrot (x 1..10): front porch, two pens, back breezeway step ----
  porch_run(g, 1, 10, 7, [1, 5, 6, 10], "spruce_fence", "spruce_planks", 1, { post: "stripped_oak_log", gap: [5, 6] });
  front_steps(g, 5, 6, 1, 6);
  front_steps(g, 5, 6, 1, 16, { facing: "north" });
  win(g, 2, 4, 9, "north", 1, 2);
  win(g, 9, 4, 9, "north", 1, 2);
  shutter(g, [3, 4, 8], "north", "spruce", { height: 2 });
  shutter(g, [8, 4, 8], "north", "spruce", { height: 2 });
  win(g, 9, 4, 15, "south", 1, 2);
  door(g, 4, 3, 12, "east", "spruce");
  door(g, 7, 3, 12, "west", "spruce");
  win(g, 1, 9, 12, "west", 1, 1);
  win(g, 10, 9, 12, "east", 1, 1);
  hanging_lantern(g, 3, 5, 7);
  hanging_lantern(g, 8, 5, 7);

  // ---- plot 1 camelback (x 15..20): front double door, porch, side and hump windows ----
  porch_run(g, 15, 20, 7, [15, 20], "acacia_fence", "spruce_planks", 1, { post: "stripped_pale_oak_log", gap: [17, 18] });
  double(g, 17, 3, 9, "north", "acacia");
  front_steps(g, 17, 18, 1, 6);
  win(g, 16, 4, 9, "north", 1, 2);
  win(g, 19, 4, 9, "north", 1, 2);
  shutter(g, [15, 4, 8], "north", "mangrove", { height: 2 });
  shutter(g, [20, 4, 8], "north", "mangrove", { height: 2 });
  win(g, 17, 8, 9, "north", 2, 1); // gable vent
  win(g, 17, 10, 13, "north", 2, 1); // hump window over the front roof
  win(g, 15, 4, 11, "west", 1, 2);
  win(g, 15, 4, 16, "west", 1, 2);
  win(g, 20, 4, 11, "east", 1, 2);
  win(g, 20, 4, 16, "east", 1, 2);
  win(g, 15, 9, 16, "west", 1, 2);
  win(g, 20, 9, 14, "east", 1, 2);
  win(g, 20, 9, 16, "east", 1, 2);
  win(g, 17, 4, 17, "south", 2, 2);
  win(g, 17, 9, 17, "south", 2, 2);
  hanging_lantern(g, 16, 5, 7);
  hanging_lantern(g, 19, 5, 7);

  // ---- plot 2 I-house (x 25..34): two-storey porch, 3-bay front, end and back openings ----
  porch_run(g, 25, 34, 7, [25, 28, 31, 34], "pale_oak_fence", "spruce_planks", 2, { post: "stripped_pale_oak_log", gap: [29, 30] });
  double(g, 29, 3, 9, "north", "pale_oak");
  win(g, 29, 5, 9, "north", 2, 1); // transom
  double(g, 29, 8, 9, "north", "pale_oak"); // gallery doors
  front_steps(g, 29, 30, 1, 6);
  for (const y of [4, 9]) {
    for (const x of [27, 32]) {
      win(g, x, y, 9, "north", 1, 2);
      shutter_pair(g, x, y, 9, "north", "warped", { height: 2 });
    }
  }
  for (const x of [25, 34]) {
    const face = x === 25 ? "west" : "east";
    for (const y of [4, 9]) for (const z of [10, 14]) win(g, x, y, z, face, 1, 2);
  }
  door(g, 29, 3, 16, "south", "pale_oak");
  for (const y of [4, 9]) for (const x of [27, 32]) win(g, x, y, 16, "south", 1, 2);
  if (g.isAir(29, 2, 17)) g.set(29, 2, 17, ...B.slab("smooth_quartz", "top")); // back stoop
  hanging_lantern(g, 27, 6, 8);
  hanging_lantern(g, 32, 6, 8);

  // ---- plot 3 pyramid cottage (x 37..46): porch, double door, shuttered front, back door ----
  porch_run(g, 37, 46, 7, [37, 40, 43, 46], "dark_oak_fence", "spruce_planks", 1, { post: "stripped_dark_oak_log", gap: [41, 42] });
  double(g, 41, 3, 9, "north", "mangrove");
  front_steps(g, 41, 42, 1, 6);
  win(g, 39, 4, 9, "north", 1, 2);
  win(g, 44, 4, 9, "north", 1, 2);
  shutter_pair(g, 39, 4, 9, "north", "mangrove", { height: 2 });
  shutter_pair(g, 44, 4, 9, "north", "mangrove", { height: 2 });
  win(g, 37, 4, 11, "west", 1, 2);
  win(g, 37, 4, 15, "west", 1, 2);
  win(g, 46, 4, 11, "east", 1, 2);
  win(g, 46, 4, 15, "east", 1, 2);
  door(g, 41, 3, 17, "south", "mangrove");
  win(g, 39, 4, 17, "south", 1, 2);
  win(g, 44, 4, 17, "south", 1, 2);
  hanging_lantern(g, 39, 5, 7);
  hanging_lantern(g, 44, 5, 7);

  // ---- plot 4 boarding house (x 49..58): long porch, hanging sign, board-and-batten windows ----
  porch_run(g, 49, 58, 7, [49, 52, 55, 58], "spruce_fence", "spruce_planks", 1, { post: "stripped_oak_log", gap: [53, 54] });
  double(g, 53, 3, 9, "north", "spruce");
  front_steps(g, 53, 54, 1, 6);
  win(g, 50, 4, 9, "north", 2, 2);
  win(g, 56, 4, 9, "north", 2, 2);
  win(g, 50, 9, 9, "north", 2, 2);
  win(g, 53, 9, 9, "north", 2, 2);
  win(g, 56, 9, 9, "north", 2, 2);
  porch_sign(g, "BOARDING", 53, 3, 8);
  hanging_lantern(g, 51, 5, 7);
  hanging_lantern(g, 56, 5, 7);
  win(g, 49, 4, 15, "west", 1, 2);
  win(g, 49, 9, 15, "west", 1, 2);
  for (const z of [11, 14]) {
    win(g, 58, 4, z, "east", 1, 2);
    win(g, 58, 9, z, "east", 1, 2);
  }
  door(g, 56, 3, 16, "south", "spruce");
  win(g, 51, 4, 16, "south", 1, 2);
  win(g, 53, 4, 16, "south", 1, 2);
  win(g, 51, 9, 16, "south", 1, 2);
  win(g, 56, 9, 16, "south", 1, 2);

  // ---- plot 5 work yard: smokehouse door and gable vent ----
  door(g, 63, 1, 12, "north", "spruce");
  louvre(g, 63, 6, 12, "south", "spruce");

  // ---- plot 7 bungalow (x 85..94): deep porch on tapered posts, brick steps, door, paired windows ----
  for (let x = 85; x <= 94; x++) {
    for (let z = 7; z <= 9; z++) if (g.isAir(x, 2, z)) g.set(x, 2, z, "spruce_planks", {});
    if (g.isAir(x, 6, 7)) g.set(x, 6, 7, "stripped_pale_oak_log", { axis: "x" });
  }
  for (const x of [85, 88, 91, 94]) taperedPost(g, x, 3, 7);
  front_steps(g, 88, 91, 1, 6, { material: "brick" });
  if (g.isAir(87, 1, 6)) g.set(87, 1, 6, "brick_wall", {});
  if (g.isAir(92, 1, 6)) g.set(92, 1, 6, "brick_wall", {});
  door(g, 89, 3, 10, "north", "spruce");
  win(g, 90, 3, 10, "north", 1, 2); // sidelight
  win(g, 86, 4, 10, "north", 2, 2);
  win(g, 92, 4, 10, "north", 2, 2);
  win(g, 85, 4, 15, "west", 2, 2);
  win(g, 94, 4, 15, "east", 2, 2);
  win(g, 94, 4, 12, "east", 1, 2);
  door(g, 88, 3, 17, "south", "spruce");
  win(g, 92, 4, 17, "south", 2, 2);
  louvre(g, 89, 8, 7, "south", "spruce");
  louvre(g, 90, 8, 7, "south", "spruce");
  hanging_lantern(g, 86, 5, 7);
  hanging_lantern(g, 93, 5, 7);
}

// Part: Shell B plots 4-7: boarding house shell (plot 4), smokehouse crib and ham racks (plot 5), bungalow brick shell (plot 7).
// The plot 4 flight (z15) belongs to parts/stairs.mjs, built before this part: its upper-floor cells (x53..57 z15) are left clear.
// The chimney reserved cells (x49..50 z12..13 plot 4, x85..86 z13..14 plot 7) and every opening stay air for later parts.
import { B, carve } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { pier_line, clapboard_wall, log_crib_wall, ham_rack } from "../vocab.mjs";

const inBox = (x, y, z, boxes) => boxes.some(([a, b, c, d, e, f]) => x >= a && x <= d && y >= b && y <= e && z >= c && z <= f);

// ---- plot 4: boarding house, two storeys, side gable -------------------------------------------------------------
const BOARDING_OPEN = [
  [53, 3, 9, 54, 4, 9],                                     // front double door
  [50, 4, 9, 51, 5, 9], [56, 4, 9, 57, 5, 9],               // front ground windows
  [50, 9, 9, 51, 10, 9], [53, 9, 9, 54, 10, 9], [56, 9, 9, 57, 10, 9], // front upper windows
  [49, 4, 15, 49, 5, 15], [49, 9, 15, 49, 10, 15],          // west end windows
  [58, 4, 11, 58, 5, 11], [58, 9, 11, 58, 10, 11],          // east end windows z11
  [58, 4, 14, 58, 5, 14], [58, 9, 14, 58, 10, 14],          // east end windows z14
  [56, 3, 16, 56, 4, 16],                                   // back door
  [51, 4, 16, 51, 5, 16], [53, 4, 16, 53, 5, 16],           // back ground windows
  [51, 9, 16, 51, 10, 16], [56, 9, 16, 56, 10, 16],         // back upper windows
  [49, 3, 12, 49, 11, 13],                                  // kitchen chimney breast (parts/chimneys.mjs)
];
const CHIMNEY_4 = (x, z) => (x === 49 || x === 50) && (z === 12 || z === 13);

function boarding(g) {
  const x0 = 49, x1 = 58, z0 = 9, z1 = 16;
  // piers on the outline, cobble, spruce skirt between; the chimney footing stays clear
  pier_line(g, x0, z0, x1, z1, "cobblestone", { y: 1, h: 1, skirt: "spruce_fence" });
  carve(g, [49, 1, 12], [49, 1, 13]);
  // deck and floors (y2 ground deck, y7 upper floor), skipping the chimney and the flight's clear cells
  for (let x = x0; x <= x1; x++) for (let z = z0; z <= z1; z++) {
    if (!CHIMNEY_4(x, z)) g.set(x, 2, z, "spruce_planks");
  }
  for (let x = 50; x <= 57; x++) for (let z = 10; z <= 15; z++) {
    if (CHIMNEY_4(x, z) || (z === 15 && x >= 53)) continue;
    g.set(x, 7, z, "spruce_planks");
  }
  // walls: mangrove field, stripped oak corners and plates (y3 base course, y11 head)
  clapboard_wall(g, [x0, 3, z0, x1, 11, z1], "mangrove_planks", "stripped_oak_log", { open: BOARDING_OPEN });
  // board-and-batten: battens at x52 and x55 on the front and back (no openings on those columns)
  for (const z of [z0, z1]) for (const x of [52, 55]) for (let y = 4; y <= 10; y++) {
    if (y !== 7) g.set(x, y, z, ...B.pillar("stripped_oak_log", "y"));
  }
  // belt course at y7 all round (floor line), axis along each run
  for (let x = 50; x <= 57; x++) {
    g.set(x, 7, z0, ...B.pillar("stripped_oak_log", "x"));
    g.set(x, 7, z1, ...B.pillar("stripped_oak_log", "x"));
  }
  for (let z = 10; z <= 15; z++) {
    if (CHIMNEY_4(49, z)) continue;
    g.set(x0, 7, z, ...B.pillar("stripped_oak_log", "z"));
    g.set(x1, 7, z, ...B.pillar("stripped_oak_log", "z"));
  }
  // upper partition z13 (doors x51 and x56) and the bunk-room wall x54 z10..12
  for (let x = 50; x <= 57; x++) for (let y = 8; y <= 11; y++) {
    if ((x === 51 || x === 56) && y <= 9) continue;
    if (CHIMNEY_4(x, 13)) continue;                         // the breast of the chimney runs through z13 at x50
    g.set(x, y, 13, "mangrove_planks");
  }
  for (let z = 10; z <= 12; z++) for (let y = 8; y <= 11; y++) g.set(54, y, z, "mangrove_planks");
}

// ---- plot 5: smokehouse, log crib on a fieldstone plinth, front gable ---------------------------------------------
function smokehouse(g) {
  const door = (x, z) => x === 63 && z === 12;               // gap in the plinth for spruce_door x63 z12
  for (let x = 61; x <= 65; x++) for (let z = 12; z <= 16; z++) {
    if (x !== 61 && x !== 65 && z !== 12 && z !== 16) continue; // ring only
    if (!door(x, z)) g.set(x, 1, z, "cobblestone");
  }
  for (let x = 62; x <= 64; x++) for (let z = 13; z <= 15; z++) g.set(x, 0, z, "packed_mud");
  log_crib_wall(g, [61, 2, 12, 65, 4, 16], "stripped_spruce_log", {
    keep: [[63, 2, 12, 63, 2, 12], [63, 2, 16, 63, 2, 16]],  // door head, and the 1x1 flue hole to the smoker
  });
  // tie beams (axis z) over the hams, y4
  for (const x of [62, 64]) for (let z = 13; z <= 15; z++) g.set(x, 4, z, ...B.pillar("stripped_oak_log", "z"));
  ham_rack(g, [62, 64], [13, 14, 15], 3);
}

// ---- plot 7: 1920s bungalow, brick walls on a brick foundation ---------------------------------------------------
const BUNGALOW_OPEN = [
  [89, 3, 10, 89, 4, 10],                                   // front door
  [90, 3, 10, 90, 4, 10],                                   // sidelight (glass, later)
  [86, 4, 10, 87, 5, 10], [92, 4, 10, 93, 5, 10],           // front paired windows
  [85, 3, 13, 85, 6, 14],                                   // west chimney footprint (parts/chimneys.mjs)
  [85, 4, 15, 85, 5, 16],                                   // west window (kitchen)
  [94, 4, 15, 94, 5, 16], [94, 4, 12, 94, 5, 12],           // east windows
  [88, 3, 17, 88, 4, 17], [92, 4, 17, 93, 5, 17],           // back door and window
];
const CHIMNEY_7 = (x, z) => x >= 85 && x <= 86 && z >= 13 && z <= 14;

function bungalow(g) {
  // continuous brick foundation y1 under body and porch; the chimney footing stays clear
  for (let x = 85; x <= 94; x++) for (let z = 7; z <= 17; z++) {
    if (!CHIMNEY_7(x, z)) g.set(x, 1, z, "bricks");
  }
  // floor deck y2 under the body
  for (let x = 85; x <= 94; x++) for (let z = 10; z <= 17; z++) {
    if (!CHIMNEY_7(x, z)) g.set(x, 2, z, "spruce_planks");
  }
  // brick walls y3..6, stripped pale oak corners and head plate y6
  clapboard_wall(g, [85, 3, 10, 94, 6, 17], "bricks", "stripped_pale_oak_log", { open: BUNGALOW_OPEN });
  // the y3 plate reads as brick, not white trim: base course is brick
  for (let x = 85; x <= 94; x++) for (const z of [10, 17]) {
    if (!inBox(x, 3, z, BUNGALOW_OPEN) && !((x === 85 || x === 94) && (z === 10 || z === 17))) g.set(x, 3, z, "bricks");
  }
  for (let z = 10; z <= 17; z++) for (const x of [85, 94]) {
    if (!inBox(x, 3, z, BUNGALOW_OPEN) && !((z === 10 || z === 17))) g.set(x, 3, z, "bricks");
  }
  // interior partitions, spruce planks y3..6: z14 (door x88 to the kitchen, door x91 to the bedroom), x90 z15..16
  for (let x = 87; x <= 93; x++) for (let y = 3; y <= 6; y++) {
    if ((x === 88 || x === 91) && y <= 4) continue;
    g.set(x, y, 14, "spruce_planks");
  }
  for (let z = 15; z <= 16; z++) for (let y = 3; y <= 6; y++) g.set(90, y, z, "spruce_planks");
}

export function build(g) {
  boarding(g);
  smokehouse(g);
  bungalow(g);
}

// Part: room: Boarding house kitchen-hall (interior, inside box x50..57 y3..6 z10..15).
// Focal piece: the lit smoker at the chimney breast (x51 z12, set by the chimneys part), seen from the double door (x53..54 z9).
// Long table x52..55 z11..12 (spruce fence legs, top slabs at y4), benches south of it, barrels by the west wall.
// Lanes: door -> z10 row -> east lane x56 down to z14. The back door (x56 z16) is behind the stair flight's foot, so the
// route through the hall is the east lane. The west wing (the smoker, barrels, x50..51) is closed off by fences: one at
// x52 z10 and a run at x52..54 z14 (fences do not step up, barrels and the smoker do), with a barrel cupboard at z15.
// Light: smoker plus three hanging lanterns under the y7 ceiling.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  const legend = {
    b: ["barrel", { facing: "up" }],
    f: "spruce_fence",
    N:["spruce_stairs", { facing: "south" }],
    T: ["spruce_slab", { type: "top" }],
    C: "cauldron",
    L: ["lantern", { hanging: "true" }],
    l: ["lantern", { hanging: "false" }],
  };
  // Rows run along +x (x50..57), successive rows along +z (z10..15). Layers are y3, y4, y5, y6.
  layers(g, [50, 3, 10], legend, [
    // y3: barrel, table legs, smoker, benches
    ["b f     ", "bbf  f  ", "  f  f  ", "  f  N  ", "  fff   ", "  bbb   "],
    // y4: table top (top slabs over x52..55 z11..12); a standing lantern on the barrel at x50 z10
    ["l       ", "  TTTT  ", "  TTTT  ", "        ", "        ", "        "],
    // y5: cauldron on the table
    ["        ", "    C   ", "        ", "        ", "        ", "        "],
    // y6: hanging lanterns under the ceiling
    [" L      ", "       L", "   L    ", "        ", "L     L ", "        "],
  ]);
}

